/* Conservative read-only note extraction. Existing current criteria always win. */
(function(root){'use strict';
const keys=['tipo_operazione_cercata','tipologia_cercata','zona_cercata','budget_min','budget_max','camere_min','superficie_min'];
function derive(c){
 if(keys.some(k=>c[k]!==null&&c[k]!==undefined&&c[k]!==''))return {mode:'existing',fields:{},source:null};
 const note=String(c.note||'');
 const m=note.match(/\b(?:cerca|cercano|cerco)\b[^\n!?]*/i);
 if(!m||/se ti contattano via chat, cerca/i.test(note)||/cerca di rispondere/i.test(m[0]))return{mode:'empty',fields:{},source:null};
 const q=m[0],s=q.toLowerCase(),fields={};
 if(/\baffitto\b/.test(s)&&!/\b(acq|acquisto|vendita)\b/.test(s))fields.tipo_operazione_cercata='affitto';
 if(/\b(acq|acquisto)\b/.test(s)&&!/\baffitto\b/.test(s))fields.tipo_operazione_cercata='vendita';
 const direct=s.match(/^(?:cerca|cercano|cerco)\s+(?:(?:un|una|in|app|appartamento)\s+)?(casa singola|appartamento|negozio|capannone|ufficio)\b/);
 if(direct&&!/\b(?:o|oppure)\b/.test(s)&&!(s.includes('ufficio')&&s.includes('negozio')))fields.tipologia_cercata=direct[1];
 const budget=q.match(/\b(?:max|massimo)\s+(\d{1,3}(?:\.\d{3})*(?:,\d{2})?|\d+)\s*(k|euro|€)?(?=\s|$)/i);
 if(budget&&!/[\d]\s*[\/-]\s*[\d]/.test(q)&&!/[\d]\s+o\s+[\d]/i.test(q)){let n=Number(budget[1].replace(/\./g,'').replace(',','.'));if(budget[2]?.toLowerCase()==='k')n*=1000;if(n>=100&&Number.isFinite(n))fields.budget_max=n;}
 return{mode:Object.keys(fields).length?'derived':'empty',fields,source:{kind:'note_cliente_originale',quote:q,note_full:note,status:'Indicazioni dalle note originali, non confermate attuali. Campi mancanti o ambigui lasciati vuoti.'}};
}
root.RighettoRequestsFromNotes={derive};
})(typeof module==='object'?module.exports:window);

