async function attachmentIndex(){const epoch=routingEpoch;const u=await sb.auth.getUser();if(epoch!==routingEpoch||u.error||u.data?.user?.id!==window.RighettoGatedPrincipal){attachmentCache=null;throw Error('Accesso amministratore richiesto');}const authority=await sb.rpc('righetto_is_admin_request');if(authority.error||authority.data!==true||epoch!==routingEpoch)throw Error('Accesso amministratore richiesto');const key=u.data.user.id+'|'+attachmentHash;if(attachmentCache?.key===key)return attachmentCache.promise;const promise=(async()=>{const r=await sb.storage.from('documenti').download(attachmentObject);if(r.error||!r.data)throw Error('Indice archivio privato non leggibile');const raw=await r.data.arrayBuffer();if(await sha(raw)!==attachmentHash)throw Error('Integrità archivio non verificata');const m=JSON.parse(new TextDecoder().decode(raw));if(m.schema!==1||!Array.isArray(m.entries)||!/^[a-f0-9]{40}$/.test(m.archive_commit))throw Error('Formato archivio non valido');const ids=new Set(),olds=new Set();for(const e of m.entries){if(ids.has(e.client_id)||olds.has(e.legacy_id)||!/^\d{1,12}$/.test(e.legacy_id)||!Array.isArray(e.files)||e.files.some(x=>typeof x!=='string'||!x||/[\/\\\x00-\x1f]/.test(x)))throw Error('Identità o nomi archivio non validi');ids.add(e.client_id);olds.add(e.legacy_id);}if(epoch!==routingEpoch)throw Error('Sessione cambiata');return m;})();attachmentCache={key,promise};try{return await promise;}catch(e){if(attachmentCache?.promise===promise)attachmentCache=null;throw e;}}
